from __future__ import annotations

REQUIRED_PROVIDER_BUDGET_FIELDS = (
    "provider",
    "daily_cap_usd",
    "monthly_cap_usd",
    "alert_threshold_pct",
    "owner",
)


def provider_budget_warnings(policy: dict[str, object]) -> tuple[str, ...]:
    warnings: list[str] = []
    for field in REQUIRED_PROVIDER_BUDGET_FIELDS:
        if field not in policy:
            warnings.append(f"{field}_missing")

    daily_cap = policy.get("daily_cap_usd")
    monthly_cap = policy.get("monthly_cap_usd")
    threshold = policy.get("alert_threshold_pct")

    if not isinstance(daily_cap, (int, float)) or daily_cap <= 0:
        warnings.append("daily_cap_usd_must_be_positive")
    if not isinstance(monthly_cap, (int, float)) or monthly_cap <= 0:
        warnings.append("monthly_cap_usd_must_be_positive")
    if isinstance(daily_cap, (int, float)) and isinstance(monthly_cap, (int, float)) and monthly_cap < daily_cap:
        warnings.append("monthly_cap_usd_must_cover_daily_cap")
    if not isinstance(threshold, (int, float)) or not 1 <= threshold <= 100:
        warnings.append("alert_threshold_pct_must_be_1_to_100")

    return tuple(warnings)


def provider_budget_is_safe(policy: dict[str, object]) -> bool:
    return not provider_budget_warnings(policy)

from __future__ import annotations


def retrieval_policy_warnings(policy: dict[str, object]) -> tuple[str, ...]:
    warnings: list[str] = []
    min_score = policy.get("min_similarity_score")
    max_chunks = policy.get("max_chunks")
    empty_behavior = policy.get("empty_retrieval_behavior")

    if not isinstance(min_score, (int, float)) or not 0 < min_score <= 1:
        warnings.append("min_similarity_score_must_be_between_0_and_1")
    if not isinstance(max_chunks, int) or not 1 <= max_chunks <= 20:
        warnings.append("max_chunks_must_be_between_1_and_20")
    if empty_behavior not in {"answer_without_sources", "ask_clarifying_question", "escalate"}:
        warnings.append("empty_retrieval_behavior_must_be_explicit")

    return tuple(warnings)


def retrieval_policy_is_safe(policy: dict[str, object]) -> bool:
    return not retrieval_policy_warnings(policy)

from __future__ import annotations

import re

SENSITIVE_PATTERNS = {
    "email": re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}"),
    "phone": re.compile(r"(?:\+?98|0)?9\d{9}"),
    "national_id": re.compile(r"\b\d{10}\b"),
}


def detected_sensitive_fields(text: str) -> tuple[str, ...]:
    return tuple(name for name, pattern in SENSITIVE_PATTERNS.items() if pattern.search(text))


def prompt_requires_redaction(text: str) -> bool:
    return bool(detected_sensitive_fields(text))

from __future__ import annotations


def fallback_budget_warnings(policy: dict[str, object]) -> tuple[str, ...]:
    warnings: list[str] = []
    if not policy.get("fallback_alias"):
        warnings.append("fallback_alias_missing")
    estimated_cost = policy.get("estimated_cost_usd")
    request_budget = policy.get("request_budget_usd")
    if not isinstance(estimated_cost, (int, float)) or estimated_cost < 0:
        warnings.append("estimated_cost_usd_must_be_non_negative")
    if not isinstance(request_budget, (int, float)) or request_budget <= 0:
        warnings.append("request_budget_usd_must_be_positive")
    if isinstance(estimated_cost, (int, float)) and isinstance(request_budget, (int, float)) and estimated_cost > request_budget:
        warnings.append("fallback_cost_exceeds_request_budget")
    if policy.get("required_capabilities_preserved") is not True:
        warnings.append("required_capabilities_must_be_preserved")
    return tuple(warnings)


def fallback_budget_is_safe(policy: dict[str, object]) -> bool:
    return not fallback_budget_warnings(policy)

from __future__ import annotations


def chunking_profile_warnings(profile: dict[str, object]) -> tuple[str, ...]:
    warnings: list[str] = []
    chunk_size = profile.get("chunk_size")
    overlap = profile.get("overlap")
    if not isinstance(chunk_size, int) or not 200 <= chunk_size <= 4000:
        warnings.append("chunk_size_must_be_between_200_and_4000")
    if not isinstance(overlap, int) or overlap < 0:
        warnings.append("overlap_must_be_non_negative")
    if isinstance(chunk_size, int) and isinstance(overlap, int) and overlap >= chunk_size:
        warnings.append("overlap_must_be_smaller_than_chunk_size")
    if not profile.get("parser_profile"):
        warnings.append("parser_profile_missing")
    if not profile.get("embedding_model"):
        warnings.append("embedding_model_missing")
    return tuple(warnings)


def chunking_profile_is_safe(profile: dict[str, object]) -> bool:
    return not chunking_profile_warnings(profile)
